CREATE TABLE topics(
 area TEXT NOT NULL, topic TEXT NOT NULL, PRIMARY KEY(area,topic)
);
CREATE INDEX source_url_idx ON sources(url);
CREATE INDEX review_professor_idx ON reviews(professor_id,id);
CREATE VIEW current_reviews AS
 SELECT * FROM reviews WHERE id IN (SELECT max(id) FROM reviews GROUP BY professor_id);
COMMIT;
