INSERT INTO "professors" VALUES(2,'Cheng, Reynold C.K.','https://ai.hku.hk/index.php/people/academic-staff/ckcheng','ckcheng@cs.hku.hk','https://reynold.hku.hk',3,'reviewed','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. ');
INSERT INTO "professors" VALUES(3,'Dai, Bo','https://ai.hku.hk/index.php/people/academic-staff/bdai','bdai@hku.hk','https://daibo.info/',4,'reviewed','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. ');
INSERT INTO "professors" VALUES(4,'Gao, Shenghua','https://ai.hku.hk/index.php/people/academic-staff/gaosh','gaosh@hku.hk',NULL,5,'partial','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. The IDS page has inconsistent interest blocks: its biography says 3D reconstruction/image generation/video understanding, while another block lists medical informatics. Match uses the biography; needs a personal research-page cross-check.');
INSERT INTO "professors" VALUES(5,'Gašević, Dragan','https://ai.hku.hk/index.php/people/academic-staff/dgasevic','dgasevic@hku.hk','https://web26.edu.hku.hk/faculty-academics/dgasevic',6,'reviewed','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. Recruitment evidence comes from the Faculty of Education. Verify the appropriate degree home and CDS supervision arrangements.');
INSERT INTO "professors" VALUES(6,'GONG, Peng','https://ai.hku.hk/index.php/people/academic-staff/penggong','penggong@hku.hk',NULL,7,'partial','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. Courtesy appointment retained. Only the official research biography was established; a personal research homepage and recruitment statement remain unresolved.');
INSERT INTO "professors" VALUES(7,'Han, Kai','https://ai.hku.hk/index.php/people/academic-staff/kaihan','kaihanx@hku.hk','https://www.kaihan.org',8,'reviewed','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. ');
INSERT INTO "professors" VALUES(8,'Huang, Chao','https://ai.hku.hk/index.php/people/academic-staff/chuang','chuang@cs.hku.hk','https://sites.google.com/view/chaoh',9,'reviewed','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. ');
INSERT INTO "professors" VALUES(9,'Kao, Benjamin C.M.','https://ai.hku.hk/index.php/people/academic-staff/kao','kao@cs.hku.hk','https://www.cs.hku.hk/~kao',10,'partial','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. Personal homepage failed through both www.cs and i.cs routes. Official profile and departmental student-message section were checked.');
INSERT INTO "professors" VALUES(10,'Kirkley, Alec William','https://ai.hku.hk/people/academic-staff/akirkley','akirkley@hku.hk','https://aleckirkley.netlify.app/',11,'reviewed','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. ');
INSERT INTO "professors" VALUES(11,'Komura, Taku','https://ai.hku.hk/index.php/people/academic-staff/taku','taku@cs.hku.hk','https://www.cs.hku.hk/~taku',12,'reviewed','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. ');
INSERT INTO "professors" VALUES(12,'Kong, Lingkai','https://ai.hku.hk/index.php/people/academic-staff/lkkong','lingkaikong@hku.hk','https://lingkai-kong.com',13,'reviewed','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. ');
INSERT INTO "professors" VALUES(13,'Kong, Lingpeng','https://ai.hku.hk/index.php/people/academic-staff/lpk','lpk@cs.hku.hk','https://ikekonglp.github.io/',14,'partial','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. The linked NLP group landing page returned no usable text; personal homepage and official profile were readable.');
INSERT INTO "professors" VALUES(14,'Li, Hongyang','https://ai.hku.hk/index.php/people/academic-staff/hongyang','hongyang@hku.hk','https://lihongyang.info/',15,'reviewed','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. Recruitment page prioritizes HKPFS/HKU Presidential Scholarship-level candidates and directs informal contact to the academic assistant. Degree routes are evidence of possible availability, not a confirmed opening.');
INSERT INTO "professors" VALUES(15,'Liang, Yingyu','https://ai.hku.hk/index.php/people/academic-staff/yingyul','yingyul@hku.hk','https://yingyuliang.github.io/',16,'reviewed','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. ');
INSERT INTO "professors" VALUES(16,'Luo, Ping','https://ai.hku.hk/index.php/people/academic-staff/pluo','pluo@cs.hku.hk','http://luoping.me',17,'partial','First-pass review of retrieved profile/homepage text and selected research/recruitment sections; not a complete publication audit. AI division directory/profile say Professor; the school directory lists Associate Professor. Rank retained from AI source. Personal homepage timed out; official PhD invitation is undated. The Gmail recruitment contact on the official profile differs from the institutional contact field.');
