INSERT INTO "research_matches" VALUES(4,3,3,'ai_graphics','neural_rendering','City-scale learned scene reconstruction and rendering',3,75,'city-scale scene reconstruction and rendering','The cited biography identifies a rendering research series including CityNeRF and Scaffold-GS; the neural-rendering tag is an interpretation of that series.');
INSERT INTO "research_matches" VALUES(5,3,3,'agents','embodied_agents','Generative AI applied to embodied AI',2,4,'Embodied AI','Embodied AI is explicitly listed; particular agent architectures are not established in this profile.');
INSERT INTO "research_matches" VALUES(6,4,4,'generation','image_generation','Image generation and visual understanding',3,60,'image generation','The biography explicitly lists image generation. Another research-interest block on the same page lists unrelated medical topics; this inconsistency is flagged in the notes.');
INSERT INTO "research_matches" VALUES(7,5,5,'other','other','Learning analytics and human–AI interaction in education',1,6,'human-AI interaction','AI interaction and educational use of generative models are adjacent; the checked evidence does not establish visual content generation or agent construction as the main focus.');
