INSERT INTO "research_matches" VALUES(12,8,8,'agents','llm_agents','Autonomous agents and LLM applications',3,39,'Large Language Models,  Autonomous Agents','The lab explicitly lists both LLMs and autonomous agents, and links agent projects. The LLM-agent tag interprets this combined focus.');
