INSERT INTO "research_matches" VALUES(16,11,11,'generation','motion_generation','Human–scene interaction and motion synthesis',3,12,'Unified synthesis of physical human-scene interactions through task tokenization','The listed 2025 publication supports learned interaction synthesis.');
